{
  "definition_simple": "A phenomenon is something that happens and can be seen or studied, especially if it is unusual or interesting.",
  "definition_standard": "An observable fact or event, particularly one that is remarkable or of scientific interest, whose cause may be in question.",
  "pos": "noun",
  "semantic_class": "abstract",
  "sentences": [
    {"sentence": "The rainbow is a beautiful phenomenon.", "tier": "T1"},
    {"sentence": "A volcano is a natural phenomenon.", "tier": "T1"},
    {"sentence": "Scientists study the phenomenon of lightning.", "tier": "T2"},
    {"sentence": "The phenomenon of fog often confuses drivers.", "tier": "T2"},
    {"sentence": "The social phenomenon of online communication has changed the world.", "tier": "T3"},
    {"sentence": "We observed a strange phenomenon in the laboratory.", "tier": "T3"},
    {"sentence": "Global warming is a phenomenon that affects the entire planet.", "tier": "T4"},
    {"sentence": "The phenomenon of quantum entanglement baffles physicists.", "tier": "T4"},
    {"sentence": "Historical phenomenon such as the Renaissance illustrate cultural shifts.", "tier": "T5"},
    {"sentence": "The elusive phenomenon of consciousness remains poorly understood despite centuries of inquiry.", "tier": "T6"}
  ],
  "morphological_forms": [
    {"form": "phenomena", "label": "plural"},
    {"form": "phenomenon's", "label": "possessive"}
  ],
  "morphology_wrong_forms": [
    {
      "target_form": "phenomena",
      "wrong_forms": [
        {"form": "phenomenons", "explanation": "This overregularized plural mistakenly adds an English -s suffix instead of the irregular Latin plural."},
        {"form": "phenomenas", "explanation": "This form incorrectly treats the Latin plural as an English -s ending, leading to a double plural."},
        {"form": "phenomeni", "explanation": "This form erroneously applies an Italian-like -i plural to a word of Greek origin."}
      ]
    },
    {
      "target_form": "phenomenon's",
      "wrong_forms": [
        {"form": "phenomenons'", "explanation": "This form confuses plural possessive with singular possessive, using a plural base incorrectly."},
        {"form": "phenomena's", "explanation": "This uses the plural base 'phenomena' to form the singular possessive, which is incorrect."},
        {"form": "phenomenon' ", "explanation": "This omits the required apostrophe-s, producing an incomplete possessive form."}
      ]
    }
  ],
  "l1_audio_confusables": [
    {"word": "phenomena", "explanation": "The plural 'phenomena' omits the final /n/ sound of 'phenomenon', causing confusion in spoken contexts."},
    {"word": "phenom", "explanation": "The clipped form 'phenom' lacks two syllables and the final /n/ sound, leading to mishearing as a different word."},
    {"word": "phenomenal", "explanation": "The adjective 'phenomenal' adds an /l/ sound at the end and has a different stress pattern, making it audibly confusable."}
  ],
  "primary_collocate": "natural",
  "collocation_distractors": [
    {"word": "magical", "explanation": "'Magical phenomenon' implies supernatural forces, whereas 'phenomenon' is typically used in scientific or factual contexts; it is not a standard collocate."},
    {"word": "strange", "explanation": "'Strange phenomenon' is acceptable but not a fixed collocate; 'strange' is subjective and not the most natural adjective paired with 'phenomenon'."},
    {"word": "mysterious", "explanation": "'Mysterious phenomenon' is common in casual speech but lacks the technical neutrality expected of a true collocate; 'natural' is more fixed."}
  ],
  "collocation_wrong_collocate": {
    "word": "great",
    "explanation": "'Great phenomenon' is rarely used; 'great' typically collocates with 'achievement' or 'event', not with 'phenomenon' in a natural way."
  },
  "cloze_distractors": [
    {"sentence": "The Northern Lights are a natural ______.", "correct": "phenomenon", "distractors": [
      {"word": "occurrence", "explanation": "Too general; 'occurrence' lacks the specific sense of a noteworthy or scientific event that 'phenomenon' carries."},
      {"word": "event", "explanation": "Similar but less precise; 'event' does not convey the observational or scientific nuance of 'phenomenon'."},
      {"word": "sight", "explanation": "Overly visual and informal; 'sight' focuses on appearance rather than the scientific aspect of a phenomenon."}
    ]}
  ],
  "discrimination_wrong_sentences": [
    {"sentence": "He phenomenoned the effect.", "reason": "Part-of-speech error: 'phenomenon' is a noun and cannot be used as a verb; there is no verb form for this word."},
    {"sentence": "The phenomenon of the problem was solved.", "reason": "Semantic error: 'phenomenon' refers to an observed occurrence, not a cause or subject of solving; it is misused as a synonym for 'cause' or 'issue'."},
    {"sentence": "She bought a phenomenon car.", "reason": "Adjectival misuse: 'phenomenon' cannot modify a noun; the correct adjective is 'phenomenal'."}
  ],
  "spot_incorrect": {
    "sentence": "The phenomenon of tides are caused by the moon.",
    "error_description": "Subject-verb agreement error: the singular subject 'phenomenon' requires the singular verb 'is', not 'are'.",
    "corrected": "The phenomenon of tides is caused by the moon."
  },
  "word_family_forms": ["phenomenal", "phenomenally"],
  "word_family_fake_forms": [
    {"form": "phenomenify", "explanation": "Looks like a verb formed from 'phenomenon' but does not exist in standard English."},
    {"form": "phenomenization", "explanation": "Appears to be a noun meaning 'the process of becoming a phenomenon', but it is not attested."},
    {"form": "phenomenistic", "explanation": "Seems like an adjective derived from 'phenomenon', but it is not a real word."}
  ],
  "syn_ant_candidates": [
    {"word": "event", "relation": "synonym", "explanation": "An event is a specific occurrence, similar to a phenomenon in being an observable happening."},
    {"word": "occurrence", "relation": "synonym", "explanation": "An occurrence is something that takes place, like a phenomenon."},
    {"word": "non-event", "relation": "antonym", "explanation": "A non-event is something that is unremarkable and not noteworthy, opposite of a phenomenon which is often notable."},
    {"word": "nothingness", "relation": "antonym", "explanation": "Nothingness represents the absence of any event or phenomenon."}
  ],
  "particle_candidates": []
}
